#!/usr/bin/env python3
# -----------------------------------------------------------------------------
# Generate the release-notes list in web/release-notes.html from the per-release
# HTML fragments in dist/release-notes/*.md, newest-first.
#
# The dist/release-notes/<version>.md files are the same HTML embedded in the
# Sparkle appcast + GitHub releases. This stitches them into one page so the
# website carries a full changelog without a separate hand-maintained copy
# (which would drift — see the in-app Help article that did exactly that).
#
# Usage (paths optional; default to repo layout):
#   dist/web-release-notes.py [<release-notes-dir> <page-file>]
#
# Behaviour:
#   • Versions sorted semver-descending; most recent on top.
#   • Each release's own leading "SherlockEQ <v>" <h2> is replaced with a
#     styled header (version + link to the GitHub tag).
#   • Per-release "Not a medical device" / "Previous release" boilerplate is
#     dropped — the page footer carries the standing disclaimer and every
#     version is already on the one page.
#   • Only the region between the generator markers in the page is rewritten;
#     the page chrome (nav, hero, footer) is hand-authored and left untouched.
#   • Idempotent: same inputs → same output.
#
#   • 1.0 SPLIT: once any 1.x release exists, the main page shows only 1.0 and
#     later, with a link at the bottom to a secondary "pre-1.0 release notes"
#     page (web/release-notes-pre-1.0.html) that carries the 0.x archive. That
#     secondary page is DERIVED from the main page here (same chrome, so they
#     can't drift) and is intentionally not in the main nav. Until a 1.x
#     release exists this is a no-op: the main page lists every version as
#     before and no secondary page is written.
#
# Exit codes: 0 on success; non-zero only on a real error (missing dir/markers,
# no release files). ship.sh treats a non-zero result as a warning.
# -----------------------------------------------------------------------------
import glob
import os
import re
import sys

REPO = "https://github.com/smbrownai/SherlockEQ"
START = "<!-- RELEASE NOTES START (generated by dist/web-release-notes.py) -->"
END = "<!-- RELEASE NOTES END -->"
PRE_1_0_PAGE = "release-notes-pre-1.0.html"

# Section headings dropped from each per-release fragment on the changelog page.
SKIP = re.compile(r"\s*<h3>\s*(not a medical device|previous release)\s*</h3>", re.I)

# Inlined "arrow up-right" icon (Lucide `arrow-up-right`). The site dropped the
# Lucide runtime, so emit the SVG directly rather than an <i data-lucide> that
# nothing would render.
TAG_ICON = (
    '<svg style="width:12px;height:12px" viewBox="0 0 24 24" fill="none" '
    'stroke="currentColor" stroke-width="2" stroke-linecap="round" '
    'stroke-linejoin="round" aria-hidden="true" focusable="false">'
    '<path d="M7 7h10v10"/><path d="M7 17 17 7"/></svg>'
)


def version_key(version):
    m = re.match(r"(\d+)\.(\d+)\.(\d+)(?:-(.+))?$", version)
    if not m:
        return (0, 0, 0, 0, "")
    major, minor, patch, pre = m.groups()
    # A final release outranks its pre-releases of the same x.y.z.
    return (int(major), int(minor), int(patch), 0 if pre is None else -1, pre or "")


def is_modern(version):
    """1.0 and later — including 1.0 pre-releases (1.0.0-beta.1). The split is
    by major version, so a 1.0 beta lands on the modern page, not the archive."""
    m = re.match(r"(\d+)\.", version)
    return bool(m) and int(m.group(1)) >= 1


def clean_body(fragment):
    """Drop the leading 'SherlockEQ <v>' heading and the boilerplate sections,
    keeping the summary paragraph and all real content sections (including
    historical ones like Acknowledgments / 'If you installed …')."""
    frag = fragment.strip()
    # Split into the lead (h2 + summary) and one chunk per <h3> section.
    chunks = re.split(r"(?=<h3>)", frag)
    lead, sections = chunks[0], chunks[1:]
    # Strip the release's own <h2> title — the page renders its own header.
    lead = re.sub(r"^\s*<h2>.*?</h2>\s*", "", lead, count=1, flags=re.DOTALL | re.I)
    kept = [s for s in sections if not SKIP.match(s)]
    body = (lead + "".join(kept)).strip()
    # Re-indent each top-level line to sit inside the article markup.
    return "\n".join(
        ("            " + line if line.strip() else "") for line in body.splitlines()
    )


def render_article(version, fragment):
    tag = f"v{version}"
    body = clean_body(fragment)
    return (
        f'        <article class="rn-item" id="{tag}">\n'
        f'          <div class="rn-head">\n'
        f'            <h2>{version}</h2>\n'
        f'            <a class="rn-tag" href="{REPO}/releases/tag/{tag}">'
        f"{tag} on GitHub {TAG_ICON}</a>\n"
        f'          </div>\n'
        f'          <div class="rn-body">\n'
        f"{body}\n"
        f'          </div>\n'
        f"        </article>"
    )


def render_block(articles, trailing=""):
    """The full generated region: articles plus an optional trailing snippet
    (e.g. the pre-1.0 archive link), wrapped in the markers."""
    body = "\n\n".join(articles)
    if trailing:
        body = f"{body}\n\n{trailing}"
    return f"{START}\n{body}\n        {END}"


def replace_region(html, block):
    return re.sub(
        re.escape(START) + r".*?" + re.escape(END),
        lambda _: block,
        html,
        flags=re.DOTALL,
    )


def derive_pre_1_0_page(main_html, legacy_block):
    """Build the secondary pre-1.0 page from the (already-updated) main page so
    the two share one source of chrome. Swap the head/hero wording, drop the
    nav 'current page' marker, and replace the article region with the 0.x
    archive."""
    html = main_html
    html = html.replace(
        "<title>SherlockEQ — release notes</title>",
        "<title>SherlockEQ — pre-1.0 release notes</title>",
    )
    html = re.sub(
        r'(<meta name="description" content=")[^"]*(")',
        r"\1Archived release notes for SherlockEQ versions before 1.0, newest "
        r"first — the full 0.x history.\2",
        html,
        count=1,
    )
    # Not the current nav destination — "Release notes" still points to the
    # live page.
    html = html.replace(
        '<a href="release-notes.html" aria-current="page">Release notes</a>',
        '<a href="release-notes.html">Release notes</a>',
    )
    html = html.replace(
        '<div class="eyebrow">CHANGELOG · EVERY VERSION</div>',
        '<div class="eyebrow">ARCHIVE · PRE-1.0 RELEASES</div>',
    )
    html = html.replace("<h1>Release notes.</h1>", "<h1>Pre-1.0 release notes.</h1>")
    html = re.sub(
        r'<p class="lede">.*?</p>',
        '<p class="lede">\n'
        "        The 0.x history of SherlockEQ, newest first, kept for reference. "
        'For the current version and later, see the <a href="release-notes.html">'
        "release notes</a>.\n"
        "      </p>",
        html,
        count=1,
        flags=re.DOTALL,
    )
    return replace_region(html, render_block(legacy_block))


def main(argv):
    here = os.path.dirname(os.path.abspath(__file__))
    repo_root = os.path.dirname(here)
    notes_dir = argv[1] if len(argv) > 1 else os.path.join(repo_root, "dist", "release-notes")
    page = argv[2] if len(argv) > 2 else os.path.join(repo_root, "web", "release-notes.html")

    files = glob.glob(os.path.join(notes_dir, "*.md"))
    versions = []
    for f in files:
        v = os.path.splitext(os.path.basename(f))[0]
        if re.match(r"\d+\.\d+\.\d+", v):
            versions.append((v, f))
    if not versions:
        sys.stderr.write(f"error: no release-notes files in {notes_dir}\n")
        return 1
    versions.sort(key=lambda vf: version_key(vf[0]), reverse=True)

    def articles_for(items):
        return [render_article(v, open(f, encoding="utf-8").read()) for v, f in items]

    modern = [(v, f) for v, f in versions if is_modern(v)]
    legacy = [(v, f) for v, f in versions if not is_modern(v)]
    split_active = bool(modern)

    try:
        html = open(page, encoding="utf-8").read()
    except OSError as e:
        sys.stderr.write(f"error: cannot read page: {e}\n")
        return 1
    if START not in html or END not in html:
        sys.stderr.write(
            f"error: {page} is missing the generator markers\n"
            f"       {START}\n       {END}\n"
        )
        return 1

    if split_active:
        # Main page = 1.0+, with a link to the pre-1.0 archive at the bottom.
        archive_link = (
            '        <p class="rn-more">Looking for older versions? See the '
            f'<a href="{PRE_1_0_PAGE}">pre-1.0 release notes</a>.</p>'
        )
        main_html = replace_region(html, render_block(articles_for(modern), archive_link))
        open(page, "w", encoding="utf-8").write(main_html)

        # Secondary page = 0.x archive, derived from the main page's chrome.
        pre_page = os.path.join(os.path.dirname(page), PRE_1_0_PAGE)
        open(pre_page, "w", encoding="utf-8").write(
            derive_pre_1_0_page(main_html, articles_for(legacy))
        )
        print(
            f"web release notes: {len(modern)} on {os.path.basename(page)}, "
            f"{len(legacy)} on {PRE_1_0_PAGE}"
        )
    else:
        # No 1.x yet — everything on the main page, no archive page. (Pre-1.0
        # state; identical to the original single-page behaviour.)
        open(page, "w", encoding="utf-8").write(
            replace_region(html, render_block(articles_for(versions)))
        )
        print(f"web release notes: wrote {len(versions)} versions to {page}")

    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
